#include <stdlib.h>
static int cmp4(const void*a,const void*b){int x=*(int*)a,y=*(int*)b;return(x>y)-(x<y);}
int** fourSum(int*a,int n,int target,int*returnSize,int**returnColumnSizes){qsort(a,n,sizeof(int),cmp4);int cap=16,c=0;int**o=malloc(cap*sizeof(int*));int*cols=malloc(cap*sizeof(int));for(int i=0;i<n-3;i++){if(i&&a[i]==a[i-1])continue;for(int j=i+1;j<n-2;j++){if(j>i+1&&a[j]==a[j-1])continue;int l=j+1,r=n-1;while(l<r){long long s=(long long)a[i]+a[j]+a[l]+a[r];if(s<target)l++;else if(s>target)r--;else{if(c==cap){cap*=2;o=realloc(o,cap*sizeof(int*));cols=realloc(cols,cap*sizeof(int));}o[c]=malloc(4*sizeof(int));o[c][0]=a[i];o[c][1]=a[j];o[c][2]=a[l];o[c][3]=a[r];cols[c++]=4;int x=a[l],y=a[r];while(l<r&&a[l]==x)l++;while(l<r&&a[r]==y)r--;}}}}*returnSize=c;*returnColumnSizes=cols;return o;}
